static const uint16_t ARABIC_GLYPH_COUNT = 127;
// Looks up a glyph by its (already-shaped) codepoint. Returns nullptr if
// there is no glyph for that codepoint (e.g. plain ASCII, which the
// ArabicOLED renderer falls back to Adafruit_GFX's built-in font for).
//
// `static inline` keeps this header safe to include from a single .cpp
// (no ODR issues) while avoiding the overhead of a real function call
// getting left in on -O0 builds.
static inline const ArabicGlyph *arabicFindGlyph(uint16_t codepoint) {
  for (uint16_t i = 0; i < ARABIC_GLYPH_COUNT; i++) {
    if (ARABIC_GLYPH_TABLE[i].codepoint == codepoint) {
      return &ARABIC_GLYPH_TABLE[i];
    }
  }
  return nullptr;
}

